# 发送 POST 请求
try:
    response = requests.post(url, json=payload, timeout=300)
except requests.exceptions.RequestException as e:
    print(f" 网络请求异常: {e}")
    exit(1)

print("状态码:", response.status_code)
if response.status_code == 200:
    try:
        result = response.json()
        markdown_content = result.get("report", "")

        if not markdown_content:
            print(" 警告：返回的 report 为空")
        else:
            # 生成带时间戳的文件名
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"security_report_{timestamp}.md"

            # 保存到当前目录
            with open(filename, "w", encoding="utf-8") as f:
                f.write(markdown_content)

            print(f" Markdown 报告已保存到：{os.path.abspath(filename)}")
            print("\n--- 报告预览（前200字符）---")
            preview = markdown_content[:200]
            if len(markdown_content) > 200:
                preview += "..."
            print(preview)

    except ValueError as e:
        print(f" 响应不是有效的 JSON: {e}")
        print("原始响应:", response.text)
    except Exception as e:
        print(f" 解析或保存失败: {e}")
else:
    print(" 请求失败，响应内容：")
    print(response.text)